function loadPurchaseOrders(){
  if(poLoading)return;
  const loading={company,bundle:data?.purchaseOrders};
  poLoading=loading;poLoadError='';
  const listVisible=()=>['dashboard','po','pohistory','payments','history'].includes(view);
  const ownsRead=()=>poLoading===loading&&company===loading.company&&data?.purchaseOrders===loading.bundle;
  if(poData&&data&&listVisible())render();
  readOperation('PURCHASE_ORDERS_REQUEST').then(result=>{
    if(!ownsRead())return;
    if(result.company!==loading.company||!Array.isArray(result.orders))throw Error('采购单回执不完整。');
    poData=result;renderTaskSignals();
  }).catch(error=>{
    if(ownsRead())poLoadError=error.message;
  }).finally(()=>{
    if(poLoading!==loading)return;
    poLoading=null;
    if(company===loading.company&&listVisible())render();
  });
}
